using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using System.Windows.Media;using System.Windows.Media.Imaging;
class ResetCountdownTests {
 static int failed;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static void Check(bool b,string n){Console.WriteLine((b?"PASS ":"FAIL ")+n);if(!b)failed++;}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var now=new DateTime(2026,10,22,9,0,0,DateTimeKind.Utc);Check(BubbleLogic.TimeLeft(TimeSpan.FromSeconds(272))=="4分 32秒","remaining minutes and seconds");Check(BubbleLogic.TimeLeft(TimeSpan.FromSeconds(.2))=="1秒","subsecond time rounds up");Check(BubbleLogic.TimeLeft(TimeSpan.FromSeconds(-1))=="0秒","expired duration never negative");Check(BubbleLogic.TimeLeft(TimeSpan.FromDays(2)+TimeSpan.FromHours(3))=="2天 3小时 0秒","long windows retain days and hours");
 var sample=new CodexQuotaSnapshot{AccountKey="test",CheckedUtc=now};sample.Windows.Add(new CodexQuotaWindow{Minutes=300,Remaining=20,ResetUtc=now.AddSeconds(272)});sample.Windows.Add(new CodexQuotaWindow{Minutes=10080,Remaining=10,ResetUtc=now.AddSeconds(120)});var reader=new CodexQuotaReader();var cfg=new CodexQuotaConfig();var notices=reader.ResetReminderNotices(sample,cfg,now);Check(notices.Length==2,"both quota windows emit countdown notices");Check(notices[0].Text.Contains("4分 32秒")&&notices[1].Text.Contains("周额度"),"notice text identifies window and remaining duration");Check(reader.ResetReminderNotices(sample,cfg,now).Length==0,"countdown does not repeat audio every tick");Check(new CodexQuotaReader().ResetReminderNotices(sample,new CodexQuotaConfig{ResetReminder=false},now).Length==0,"manual reminder switch respected");Check(VoicePolicy.NotificationEvent("codex-reset-soon:300:1",3)=="reminder","existing reminder voice selected once");
 var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;SpeechBubble bubble=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;((BubbleQueue)Get(pet,"messages")).Clear();var deadline=DateTime.UtcNow.AddSeconds(272);typeof(ConanPet).GetMethod("NotifyUser",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pet,new object[]{"codex-reset-soon:300:"+deadline.Ticks,"测试额度重置",3});var message=((BubbleQueue)Get(pet,"messages")).Current;Check(message!=null&&message.CountdownUtc==deadline&&message.CountdownLabel.Contains("五小时"),"notification dispatch preserves deadline and quota window");Check(BubbleLogic.Heading(message)=="Codex 额度重置提醒","dedicated reset reminder heading");
 bubble=new SpeechBubble();var area=SystemParameters.WorkArea;bubble.Render(message,0,area.Left+area.Width/2,area.Top+320,area.Top+530,area);var body=(TextBlock)Get(bubble,"body");string first=body.Text;System.Threading.Thread.Sleep(1100);bubble.Render(message,0,area.Left+area.Width/2,area.Top+320,area.Top+530,area);Check(body.Text!=first&&body.Text.Contains("距离预计重置还有"),"visible bubble countdown refreshes over time");bubble.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(bubble.Width),(int)Math.Ceiling(bubble.Height),96,96,PixelFormats.Pbgra32);bitmap.Render(bubble);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(args[0],"reset-countdown.png")))encoder.Save(file);
 message.CountdownUtc=DateTime.UtcNow.AddSeconds(-1);bubble.Render(message,0,area.Left+area.Width/2,area.Top+320,area.Top+530,area);Check(message.DisplayText(DateTime.UtcNow).Contains("等待官方核验"),"zero does not claim quota recovery");Check(new BubbleMessage{Text="普通提醒"}.DisplayText(now)=="普通提醒","ordinary messages unchanged");}catch(Exception e){Console.WriteLine("FAIL "+e);failed++;}finally{if(bubble!=null)bubble.Close();if(pet!=null)pet.Close();app.Shutdown();}return failed==0?0:1;
 }
}
